-- 示例：调试一个数据同步存储过程
CREATE PROCEDURE dbo.usp_SyncData
    @SourceDate DATE,
    @BatchSize INT = 1000
AS
BEGIN
    SET NOCOUNT ON;

    -- 建议：在调试开始处设置断点
    DECLARE @CurrentBatch INT = 0;
    DECLARE @TotalRecords INT;

    -- 获取待同步数据量
    SELECT @TotalRecords = COUNT(*)
    FROM staging.SourceTable
    WHERE sync_date >= @SourceDate;

    -- 分批处理
    WHILE @CurrentBatch < @TotalRecords
    BEGIN
        -- 此处设置条件断点：@CurrentBatch = 100
        INSERT INTO target.DestinationTable
        SELECT TOP (@BatchSize) *
        FROM staging.SourceTable
        WHERE sync_date >= @SourceDate
        ORDER BY sync_date
        OFFSET @CurrentBatch ROWS
        FETCH NEXT @BatchSize ROWS ONLY;

        SET @CurrentBatch += @BatchSize;

        -- 调试时检查进度
        PRINT 'Processed: ' + CAST(@CurrentBatch AS VARCHAR);
    END

    PRINT 'Sync complete. Total: ' + CAST(@TotalRecords AS VARCHAR);
END;
GO

