-- 模板缩写: proc
CREATE OR ALTER PROCEDURE dbo.usp_$NAME$
    @Param1 $TYPE1$,
    @Param2 $TYPE2$ = $DEFAULT$
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Result INT = 0;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- TODO: 业务逻辑

        COMMIT TRANSACTION;
        SET @Result = 1;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        DECLARE @ErrorSeverity INT = ERROR_SEVERITY();
        DECLARE @ErrorState INT = ERROR_STATE();

        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);
        SET @Result = 0;
    END CATCH

    RETURN @Result;
END;
GO

