-- 在存储过程的关键逻辑处添加 PRINT 语句
CREATE OR ALTER PROCEDURE dbo.usp_SalesReport
    @StartDate DATE,
    @EndDate DATE,
    @Region VARCHAR(50) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    PRINT '开始执行存储过程...';
    PRINT CONCAT('参数: @StartDate=', @StartDate, 
                 ', @EndDate=', @EndDate);

    -- 断点1: 数据准备
    DECLARE @TempData TABLE (
        OrderID INT,
        CustomerName NVARCHAR(100),
        TotalAmount DECIMAL(18,2),
        OrderDate DATE
    );

    PRINT '准备数据...';

    INSERT INTO @TempData
    SELECT 
        o.OrderID,
        c.CustomerName,
        SUM(oi.Quantity * oi.UnitPrice) AS TotalAmount,
        o.OrderDate
    FROM dbo.Orders o
    JOIN dbo.Customers c ON o.CustomerID = c.CustomerID
    JOIN dbo.OrderItems oi ON o.OrderID = oi.OrderID
    WHERE o.OrderDate BETWEEN @StartDate AND @EndDate
    AND (@Region IS NULL OR o.Region = @Region)
    GROUP BY o.OrderID, c.CustomerName, o.OrderDate;

    PRINT CONCAT('插入记录数: ', @@ROWCOUNT);

    -- 断点2: 汇总计算
    PRINT '计算汇总...';

    SELECT 
        CustomerName,
        COUNT(*) AS OrderCount,
        SUM(TotalAmount) AS GrandTotal,
        AVG(TotalAmount) AS AvgAmount
    FROM @TempData
    GROUP BY CustomerName
    ORDER BY GrandTotal DESC;

    PRINT '存储过程执行完成';
END;

